-- Customer performance analysis
SELECT
    customer_id,
    customer_name,
    customer_segment,
    COUNT(DISTINCT order_id) AS total_orders,
    SUM(net_sales) AS total_revenue,
    SUM(profit) AS total_profit,
    ROUND(
        SUM(profit) / NULLIF(SUM(net_sales), 0) * 100,
        2
    ) AS profit_margin
FROM raw_orders
GROUP BY
    customer_id,
    customer_name,
    customer_segment
ORDER BY total_revenue DESC
LIMIT 10;



-- Revenue generated by customer 
SELECT
    customer_id,
    customer_name,
    SUM(net_sales) AS revenue,
    SUM(profit) AS Total_profit
FROM raw_orders
GROUP BY
    customer_id,
    customer_name
ORDER BY total_profit DESC
LIMIT 10;



-- customers by top profit margin 
select customer_id , customer_name , 
sum(net_sales) as total_revenue , 
sum(profit) as total_profit ,
round(sum(profit)/nullif(sum(net_sales),0)*100 , 2) as profit_margin 
from raw_orders 
group by customer_id , customer_name 
order by profit_margin desc limit 10;



-- How many orders did each customer place?
SELECT 
    customer_id,
    customer_name,
    COUNT(DISTINCT order_id) AS total_orders,
    SUM(net_sales) AS total_revenue
FROM raw_orders
GROUP BY customer_id, customer_name
ORDER BY total_orders DESC
LIMIT 10;


-- top 10 repeat customers by revenue
SELECT 
    customer_id,
    customer_name,
    COUNT(order_id) AS total_orders,
    SUM(net_sales) AS total_revenue
FROM raw_orders
GROUP BY customer_id, customer_name 
HAVING Count(order_id) > 1
ORDER BY total_revenue DESC
LIMIT 10;


--customers who generated more than $10,000 in total revenue AND placed atleast 3 orders.
SELECT 
    customer_id,
    customer_name,
    COUNT(DISTINCT order_id) AS total_orders,
    SUM(net_sales) AS total_revenue,
    ROUND(
        SUM(net_sales) / NULLIF(COUNT(DISTINCT order_id), 0),
        2
    ) AS AOV
FROM raw_orders
GROUP BY customer_id, customer_name
HAVING SUM(net_sales) > 10000 
   AND COUNT(DISTINCT order_id) > 3
ORDER BY total_revenue DESC;


--top 10 customers by profit
select customer_id , customer_name , sum(net_sales) as total_revenue,
sum(profit) as total_profit ,
round(sum(profit)/nullif(sum(net_sales),0)*100,2) as profit_margin 
from raw_orders
group by customer_id, customer_name 
order by total_profit desc;



-- customers generated more than 10,000 revenue but have a profit margin below 20%
SELECT 
    customer_id,
    customer_name,
    SUM(net_sales) AS total_revenue,
    SUM(profit) AS total_profit,
    ROUND(
        SUM(profit) / NULLIF(SUM(net_sales), 0) * 100,
        2
    ) AS profit_margin 
FROM raw_orders
GROUP BY customer_id, customer_name 
HAVING 
    SUM(net_sales) > 10000
    AND ROUND(
        SUM(profit) / NULLIF(SUM(net_sales), 0) * 100,
        2
    ) <= 20
ORDER BY total_revenue DESC;




-- Customer profitability classification
SELECT 
    customer_id,
    customer_name,
    SUM(net_sales) AS total_revenue,
    SUM(profit) AS total_profit,
    ROUND(
        SUM(profit) / NULLIF(SUM(net_sales), 0) * 100,
        2
    ) AS profit_margin,

    CASE
        WHEN SUM(profit) / NULLIF(SUM(net_sales), 0) * 100 >= 30
            THEN 'High Profit'
        WHEN SUM(profit) / NULLIF(SUM(net_sales), 0) * 100 >= 15
            THEN 'Medium Profit'
        ELSE 'Low Profit'
    END AS profit_category

FROM raw_orders
GROUP BY customer_id, customer_name
ORDER BY profit_margin DESC;



-- business segmentation
SELECT 
    customer_id,
    customer_name,
    SUM(net_sales) AS total_revenue,

    CASE
        WHEN SUM(net_sales) >= 50000 THEN 'VIP'
        WHEN SUM(net_sales) >= 25000 THEN 'HIGH VALUE'
        WHEN SUM(net_sales) >= 10000 THEN 'MEDIUM VALUE' ELSE 'LOW VALUE'    
    END AS customer_segment

FROM raw_orders
GROUP BY customer_id, customer_name
ORDER BY total_revenue DESC;



-- VIP → revenue ≥ 50,000 AND have profit margin ≥ 25%
SELECT 
    customer_id,
    customer_name,
    SUM(net_sales) AS total_revenue,
    SUM(profit) AS total_profit,
    ROUND(
        SUM(profit) / NULLIF(SUM(net_sales), 0) * 100,
        2
    ) AS profit_margin
FROM raw_orders
GROUP BY customer_id, customer_name
having SUM(net_sales) >= 50000 and 

        SUM(profit) / NULLIF(SUM(net_sales), 0) * 100 >= 25 
ORDER BY total_profit DESC;
